parts = [list(range(0,7)), list(range(7,14)), list(range(14,20))]
edges = []
for i in range(3):
    for j in range(i+1,3):
        for u in parts[i]:
            for v in parts[j]:
                edges.append((min(u,v), max(u,v)))
edges.sort()
flat = [x for pair in edges for x in pair]
print(flat)
